functions.learning_case_write_guard_v11():
CREATE OR REPLACE FUNCTION public.learning_case_write_guard_v11()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF TG_TABLE_NAME='rag_items' THEN
  IF TG_OP='INSERT' THEN
   IF NEW.source_type IS DISTINCT FROM 'case_example' THEN RETURN NEW; END IF;
  ELSIF TG_OP='DELETE' THEN
   IF OLD.source_type IS DISTINCT FROM 'case_example' THEN RETURN OLD; END IF;
   RAISE EXCEPTION 'case provenance must be retained';
  ELSE
   IF OLD.source_type IS DISTINCT FROM 'case_example' AND NEW.source_type IS DISTINCT FROM 'case_example' THEN RETURN NEW; END IF;
   IF OLD.source_type IS DISTINCT FROM NEW.source_type OR
    (to_jsonb(NEW)-ARRAY['embedding','active','approved','quality_status','learning_data','updated_at']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['embedding','active','approved','quality_status','learning_data','updated_at']) THEN
    RAISE EXCEPTION 'case content and origin immutable';
   END IF;
  END IF;
 ELSE
  IF TG_OP IN ('UPDATE','DELETE') THEN RAISE EXCEPTION 'case audit is append only'; END IF;
 END IF;
 IF current_user IS DISTINCT FROM pg_get_userbyid((SELECT proowner FROM pg_proc
   WHERE oid='public.learning_case_stage_v11(uuid)'::regprocedure)) THEN
  RAISE EXCEPTION 'case write requires controlled v11 function';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

functions.learning_case_feedback_guard_v11():
CREATE OR REPLACE FUNCTION public.learning_case_feedback_guard_v11()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE c jsonb;
BEGIN
 c := NEW.feedback_data->'learning_case_v11';
 IF TG_OP='UPDATE' AND OLD.feedback_data ? 'learning_case_v11' THEN
  IF NEW.agent_id IS DISTINCT FROM OLD.agent_id OR NEW.outgoing_message_uuid IS DISTINCT FROM OLD.outgoing_message_uuid
   OR NEW.mail_event_message_uuid IS DISTINCT FROM OLD.mail_event_message_uuid OR NEW.human_answer IS DISTINCT FROM OLD.human_answer
   OR NEW.feedback_type IS DISTINCT FROM OLD.feedback_type
   OR NEW.feedback_data->'response_source' IS DISTINCT FROM OLD.feedback_data->'response_source' THEN
   RAISE EXCEPTION 'canonical case source immutable';
  END IF;
  IF c IS NOT DISTINCT FROM OLD.feedback_data->'learning_case_v11' THEN RETURN NEW; END IF;
  IF c IS NULL OR c->>'status' IS DISTINCT FROM 'blocked' THEN
   RAISE EXCEPTION 'canonical case immutable except blocking';
  END IF;
 END IF;
 IF c IS NOT NULL AND public.learning_case_envelope_valid_v11(c) IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'invalid learning_case_v11 envelope';
 END IF;
 RETURN NEW;
END $function$

functions.learning_review_activation_guard():
CREATE OR REPLACE FUNCTION public.learning_review_activation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v public.learning_reviews; managed boolean;
BEGIN
 SELECT * INTO v FROM public.learning_reviews WHERE item_id=NEW.id;
 managed := FOUND;
 IF managed AND current_setting('libredesk.review_writer',true) IS DISTINCT FROM 'true' THEN
   RAISE EXCEPTION 'managed learning content requires review transaction';
 END IF;
 IF NEW.active THEN
  IF NEW.approved IS DISTINCT FROM true OR NEW.quality_status IS DISTINCT FROM 'approved' OR NEW.embedding IS NULL
    OR public.vector_dims(NEW.embedding) <> 1536 THEN RAISE EXCEPTION 'invalid learning publication'; END IF;
  IF NEW.source_type='employee_fact' AND
    (NEW.learning_data->>'verification_status' IS DISTINCT FROM 'human_verified'
     OR NEW.learning_data->>'factual_use_approved' IS DISTINCT FROM 'true') THEN
    RAISE EXCEPTION 'human verification required';
  END IF;
  IF managed AND (v.decision <> 'approved' OR v.publication NOT IN ('publishing','published') OR NEW.learning_data->>'approval_method' IS DISTINCT FROM 'human_review_v1') THEN
    RAISE EXCEPTION 'review decision required';
  END IF;
  IF managed AND OLD.active AND (NEW.retrieval_text IS DISTINCT FROM OLD.retrieval_text
      OR NEW.human_answer IS DISTINCT FROM OLD.human_answer OR NEW.learning_data IS DISTINCT FROM OLD.learning_data) THEN
    RAISE EXCEPTION 'published content immutable';
  END IF;
 END IF;
 RETURN NEW;
END $function$

functions.learning_case_envelope_valid_v11(c jsonb:
CREATE OR REPLACE FUNCTION public.learning_case_envelope_valid_v11(c jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE k text;
BEGIN
 IF jsonb_typeof(c) IS DISTINCT FROM 'object' OR c->'version' IS DISTINCT FROM '11'::jsonb THEN RETURN false; END IF;
 IF c->>'status' IN ('blocked','insufficient') THEN
  FOR k IN SELECT jsonb_object_keys(c) LOOP
   IF k NOT IN ('version','status','reason_code') THEN RETURN false; END IF;
  END LOOP;
  RETURN COALESCE(NOT c ? 'reason_code' OR c->>'reason_code' IN ('privacy','security','no_resolution','no_explicit_feedback','insufficient_context'),false);
 END IF;
 IF c->>'status' IS DISTINCT FROM 'staged'
  OR c->'has_human_resolution' IS DISTINCT FROM 'true'::jsonb
  OR jsonb_typeof(c->'has_explicit_feedback') IS DISTINCT FROM 'boolean'
  OR c->'requires_quality_review' IS DISTINCT FROM 'true'::jsonb
  OR jsonb_typeof(c->'feedback_type') IS DISTINCT FROM 'string'
  OR c->>'feedback_type' NOT IN ('response_feedback','manual_resolution','category_correction','general_feedback')
  OR NOT c ? 'feedback_type' THEN RETURN false; END IF;
 IF length(btrim(c->>'customer_question')) < 12 THEN RETURN false; END IF;
 FOR k IN SELECT jsonb_object_keys(c) LOOP
  IF k NOT IN ('version','status','customer_question','human_answer','feedback_reason','feedback_type',
   'original_categories','corrected_categories','has_human_resolution','has_explicit_feedback','requires_quality_review') THEN RETURN false; END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['customer_question','human_answer','feedback_reason'] LOOP
  IF jsonb_typeof(c->k) IS DISTINCT FROM 'string' OR length(c->>k) > 6000
   OR (k <> 'feedback_reason' AND length(btrim(c->>k))=0) THEN RETURN false; END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['original_categories','corrected_categories'] LOOP
  IF jsonb_typeof(c->k) IS DISTINCT FROM 'array' THEN RETURN false; END IF;
  IF jsonb_array_length(c->k)>20 OR EXISTS(SELECT FROM jsonb_array_elements(c->k) x
   WHERE jsonb_typeof(x) <> 'string' OR (x#>>'{}') !~ '^[A-Za-z][A-Za-z0-9_-]{0,63}$') THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END $function$

functions.finish_libredesk_sent_v2(p_outgoing_mess:
CREATE OR REPLACE FUNCTION public.finish_libredesk_sent_v2(p_outgoing_message_uuid text, p_outcome text)
 RETURNS TABLE(finalized boolean, outgoing_message_uuid text, outcome text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_state text;
BEGIN
  IF p_outcome NOT IN ('resolved','superseded','invalid_completion') OR p_outcome IS NULL THEN
    RETURN QUERY SELECT false,p_outgoing_message_uuid,'invalid_resolve_outcome'::text;
    RETURN;
  END IF;
  SELECT r.resolve_state INTO v_state
    FROM public.libredesk_sent_receipts_v2 AS r
    WHERE r.outgoing_message_uuid=p_outgoing_message_uuid FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false,p_outgoing_message_uuid,'receipt_not_found'::text;
    RETURN;
  END IF;
  IF v_state='pending' THEN
    UPDATE public.libredesk_sent_receipts_v2 AS r
    SET resolve_state=p_outcome,finalized_at=now()
    WHERE r.outgoing_message_uuid=p_outgoing_message_uuid;
    RETURN QUERY SELECT true,p_outgoing_message_uuid,p_outcome;
  ELSIF v_state=p_outcome THEN
    RETURN QUERY SELECT true,p_outgoing_message_uuid,v_state;
  ELSE
    RETURN QUERY SELECT false,p_outgoing_message_uuid,'terminal_outcome_conflict'::text;
  END IF;
END;
$function$

functions.learning_case_publish_v11(p_id uuid, p_r:
CREATE OR REPLACE FUNCTION public.learning_case_publish_v11(p_id uuid, p_revision bigint, p_embedding vector)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE r public.rag_items; rev bigint;
BEGIN
 SELECT * INTO r FROM public.rag_items WHERE id=p_id AND source_type='case_example' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'case not found'; END IF;
 rev := (r.learning_data->>'case_revision')::bigint;
 IF rev IS DISTINCT FROM p_revision OR r.learning_data->>'case_status' IS DISTINCT FROM 'approved'
  OR r.learning_data->>'privacy_checked' IS DISTINCT FROM 'true' OR r.learning_data->>'quality_checked' IS DISTINCT FROM 'true'
  OR r.learning_data->>'generalization_checked' IS DISTINCT FROM 'true'
  OR p_embedding IS NULL OR public.vector_dims(p_embedding)<>1536 OR public.vector_norm(p_embedding)=0 THEN
  RAISE EXCEPTION 'case publication requires current review and valid vector';
 END IF;
 PERFORM 1 FROM public.ai_feedback f WHERE id=r.feedback_id AND public.learning_case_human_source_valid_v11(f) AND feedback_data->'learning_case_v11'->>'status'='staged'
  AND md5((feedback_data->'learning_case_v11')::text)=r.learning_data->>'origin_digest' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'case origin unavailable or blocked'; END IF;
 UPDATE public.rag_items SET embedding=p_embedding,approved=true,active=true,quality_status='approved',updated_at=now(),
  learning_data=learning_data||jsonb_build_object('case_status','published','case_revision',rev+1,'publish_state','published',
   'embedding_model','text-embedding-3-small','published_at',now()) WHERE id=p_id;
 INSERT INTO public.learning_case_audit_v11(item_id,revision,action,actor) VALUES(p_id,rev+1,'publish',session_user);
 RETURN rev+1;
END $function$

functions.learning_case_review_v11(p_id uuid, p_re:
CREATE OR REPLACE FUNCTION public.learning_case_review_v11(p_id uuid, p_revision bigint, p_decision text, p_actor text, p_privacy boolean DEFAULT false, p_quality boolean DEFAULT false, p_generalization boolean DEFAULT false, p_categories jsonb DEFAULT '[]'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE r public.rag_items; rev bigint;
BEGIN
 SELECT * INTO r FROM public.rag_items WHERE id=p_id AND source_type='case_example' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'case not found'; END IF;
 rev := (r.learning_data->>'case_revision')::bigint;
 IF rev IS DISTINCT FROM p_revision OR p_decision IS NULL OR p_decision NOT IN ('approved','rejected','blocked','disabled')
  OR length(btrim(p_actor)) NOT BETWEEN 1 AND 100 OR p_actor IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='invalid case decision or revision'; END IF;
 IF p_decision='approved' THEN
  IF r.learning_data->>'case_status' IS DISTINCT FROM 'staged' OR p_privacy IS DISTINCT FROM true
   OR p_quality IS DISTINCT FROM true OR p_generalization IS DISTINCT FROM true THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='case quality review required'; END IF;
  PERFORM 1 FROM public.ai_feedback f WHERE f.id=r.feedback_id
   AND public.learning_case_human_source_valid_v11(f)
   AND f.feedback_data->'learning_case_v11'->>'status'='staged'
   AND md5((f.feedback_data->'learning_case_v11')::text)=r.learning_data->>'origin_digest' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='case origin unavailable or blocked'; END IF;
  IF jsonb_typeof(p_categories) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid confirmed categories'; END IF;
  IF EXISTS(SELECT FROM jsonb_array_elements(p_categories) x WHERE jsonb_typeof(x)<>'string'
   OR (x#>>'{}') !~ '^[A-Za-z][A-Za-z0-9_-]{0,63}$') OR jsonb_array_length(p_categories)>20 THEN RAISE EXCEPTION 'invalid confirmed categories'; END IF;
 END IF;
 UPDATE public.rag_items SET active=false,approved=false,embedding=NULL,quality_status=CASE WHEN p_decision='approved' THEN 'approved' ELSE p_decision END,
  updated_at=now(),learning_data=learning_data||jsonb_build_object('case_status',p_decision,'case_revision',rev+1,
  'publish_state',CASE WHEN p_decision='approved' THEN 'unpublished' ELSE 'blocked' END,
  'privacy_checked',p_decision='approved','quality_checked',p_decision='approved','generalization_checked',p_decision='approved',
  'confirmed_categories',CASE WHEN p_decision='approved' THEN p_categories ELSE '[]'::jsonb END,'reviewer',p_actor,'reviewed_at',now()) WHERE id=p_id;
 INSERT INTO public.learning_case_audit_v11(item_id,revision,action,actor) VALUES(p_id,rev+1,p_decision,p_actor);
 RETURN rev+1;
END $function$

functions.record_libredesk_sent_v2(p_conversation_:
CREATE OR REPLACE FUNCTION public.record_libredesk_sent_v2(p_conversation_uuid text, p_source_message_uuid text, p_outgoing_message_uuid text, p_response_source text, p_sent_message text, p_sent_at timestamp with time zone, p_agent_id text, p_expected_incoming_version text)
 RETURNS TABLE(committed boolean, outgoing_message_uuid text, needs_resolve boolean, outcome text, conversation_uuid text, expected_incoming_version text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_hash text;
  v_ins_count integer;
  v_existing_hash text;
  v_state text;
  v_latest_uuid text;
BEGIN
  IF nullif(trim(p_conversation_uuid),'') IS NULL
    OR nullif(trim(p_source_message_uuid),'') IS NULL
    OR nullif(trim(p_outgoing_message_uuid),'') IS NULL
    OR p_source_message_uuid = p_outgoing_message_uuid
    OR (p_response_source IS NOT NULL AND p_response_source NOT IN ('ai','ai_adapted','human'))
    OR p_sent_message IS NULL -- empty-string is allowed for attachments
    OR p_sent_at IS NULL
    OR p_expected_incoming_version IS NULL
    OR p_expected_incoming_version !~ '^[1-9][0-9]{0,18}$'
  THEN
    RETURN QUERY SELECT false,p_outgoing_message_uuid,false,'invalid_payload'::text,p_conversation_uuid,p_expected_incoming_version;
    RETURN;
  END IF;

  -- Source row lock serializes multiple outgoing replies to this incoming email.
  PERFORM 1 FROM public.mail_events AS m
  WHERE m.message_uuid=p_source_message_uuid
    AND m.conversation_uuid=p_conversation_uuid
    AND m.direction='inbound'
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false,p_outgoing_message_uuid,false,'source_not_found'::text,p_conversation_uuid,p_expected_incoming_version;
    RETURN;
  END IF;

  v_hash:=md5(jsonb_build_object(
    'conversation_uuid',p_conversation_uuid,
    'source_message_uuid',p_source_message_uuid,
    'outgoing_message_uuid',p_outgoing_message_uuid,
    'response_source',p_response_source,
    'sent_message',p_sent_message,
    'sent_at',to_char(p_sent_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'agent_id',p_agent_id,
    'expected_incoming_version',p_expected_incoming_version
  )::text);

  INSERT INTO public.libredesk_sent_receipts_v2 AS r
    (outgoing_message_uuid,source_message_uuid,conversation_uuid,response_source,
     agent_id,expected_incoming_version,sent_at,payload_hash)
  VALUES(p_outgoing_message_uuid,p_source_message_uuid,p_conversation_uuid,p_response_source,
     p_agent_id,p_expected_incoming_version,p_sent_at,v_hash)
  ON CONFLICT ON CONSTRAINT libredesk_sent_receipts_v2_pkey DO NOTHING;
  GET DIAGNOSTICS v_ins_count=ROW_COUNT;

  IF v_ins_count=0 THEN
    SELECT r.payload_hash,r.resolve_state INTO v_existing_hash,v_state
    FROM public.libredesk_sent_receipts_v2 AS r
    WHERE r.outgoing_message_uuid=p_outgoing_message_uuid;
    IF v_existing_hash IS DISTINCT FROM v_hash THEN
      RETURN QUERY SELECT false,p_outgoing_message_uuid,false,'duplicate_payload_mismatch'::text,p_conversation_uuid,p_expected_incoming_version;
      RETURN;
    END IF;
  ELSE
    v_state:='pending';
  END IF;

  -- Update the latest outbound response per original inbound mail only.
  SELECT r.outgoing_message_uuid INTO v_latest_uuid
  FROM public.libredesk_sent_receipts_v2 AS r
  WHERE r.source_message_uuid=p_source_message_uuid
  ORDER BY r.sent_at DESC,r.outgoing_message_uuid DESC LIMIT 1;
  IF v_latest_uuid=p_outgoing_message_uuid AND v_ins_count=1 THEN
    UPDATE public.mail_events AS m SET
      sent_message=p_sent_message,
      sent_at=p_sent_at AT TIME ZONE 'UTC',
      status='sent',
      processing_stage='complete',
      status_updated_at=now() AT TIME ZONE 'UTC',
      response_source=p_response_source,
      agent_id=COALESCE(p_agent_id,m.agent_id)
    WHERE m.message_uuid=p_source_message_uuid
      AND m.conversation_uuid=p_conversation_uuid;
    -- Do not change faq_candidate: this is Learning/Review-owned state.
  END IF;

  RETURN QUERY SELECT true,p_outgoing_message_uuid,(v_state='pending'),
    (CASE WHEN v_ins_count=0 THEN 'duplicate_accepted' ELSE 'recorded' END)::text,
    p_conversation_uuid,p_expected_incoming_version;
END;
$function$
